## 🚀 React-Specific Best Practices

### **1. Create Reusable Chart Components**

```jsx
// components/LineChart.jsx
import React, { useMemo } from 'react';
import ReactECharts from 'echarts-for-react';

export function LineChart({ data, title, color = '#5470c6' }) {
  const option = useMemo(() => ({
    title: { text: title },
    xAxis: { 
      type: 'category',
      data: data.labels 
    },
    yAxis: { type: 'value' },
    series: [{
      data: data.values,
      type: 'line',
      smooth: true,
      itemStyle: { color }
    }]
  }), [data, title, color]);

  return <ReactECharts option={option} style={{ height: 400 }} />;
}
```

### **2. Handle Events Properly**

```jsx
const onChartClick = (params) => {
  console.log('Clicked:', params);
  // params.name, params.value, params.dataIndex
};

<ReactECharts 
  option={option}
  onEvents={{
    'click': onChartClick,
    'legendselectchanged': (params) => console.log(params)
  }}
/>
```

### **3. Access Chart Instance**

```jsx
function MyChart() {
  const chartRef = useRef(null);

  const handleResetZoom = () => {
    const instance = chartRef.current.getEchartsInstance();
    instance.dispatchAction({
      type: 'restore'  // Reset zoom
    });
  };

  return (
    <>
      <button onClick={handleResetZoom}>Reset Zoom</button>
      <ReactECharts ref={chartRef} option={option} />
    </>
  );
}
```

